        String command = String.format(
            "find %s -type f -name %s 2>/dev/null | head -10",
            escapedDir,
            escapedPattern
        );

        try {
            // Execute command via bash -c
            ProcessBuilder processBuilder = new ProcessBuilder("bash", "-c", command);
            processBuilder.redirectErrorStream(false); // stderr already redirected in command
            Process process = processBuilder.start();

            // Read command output
            BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream())
            );
            String output = reader.lines().collect(Collectors.joining("\n"));

            // Wait for process to complete
            int exitCode = process.waitFor();

            // If exit code is non-zero, something went wrong (though stderr is discarded)
            if (exitCode != 0) {
                return "Error: find command failed with exit code " + exitCode;
            }

            return output;

        } catch (IOException e) {
            return "Error: IOException occurred: " + e.getMessage();
        } catch (InterruptedException e) {
            // Restore interrupted status
            Thread.currentThread().interrupt();
            return "Error: Process was interrupted: " + e.getMessage();
        }
    }

    /**
     * Escapes a string for safe use inside a single-quoted argument in bash.
     * The string is wrapped in single quotes, and any existing single quotes
     * are escaped by replacing them with the sequence: '\''
     * (end quote, escaped quote, start quote).
     *
     * @param arg the argument to escape
     * @return the escaped argument, safe for use in a bash command string
     */
    private String escapeShellArg(String arg) {
        // Replace each single quote with: '\'' (closes quote, adds escaped quote, reopens quote)
        String escaped = arg.replace("'", "'\\''");
        return "'" + escaped + "'";
    }
}
